mapper.select:
select cast(c.id as char) configVersionId,c.version_no versionNo,c.mode,cast(c.avatar_version_id as char) avatarVersionId,
  cast(c.voice_version_id as char) voiceVersionId,c.context_policy contextPolicy,c.runtime_limits runtimeLimits,lower(hex(c.config_hash)) configHash,c.published_at publishedAt
from p_app_config c where c.id=#{configVersionId} and c.application_id=#{applicationId} and c.account_id=#{accountId}
